INSERT INTO `wp_postmeta` VALUES (695,181,'_form','<!-- Formulaire de contact -->\n\n<form action=\"#\" method=\"post\">\n    <div class=\"form-container\">\n        <div class=\"info-section\">\n            <h2>Vos informations</h2>\n            [text* nom id:nom placeholder \"Votre nom\"]\n            [text prenom id:prenom placeholder \"Votre prénom\"]\n            [email* email id:email placeholder \"Votre e-mail\"]\n        </div>\n\n        <div class=\"divider\"></div>\n\n        <div class=\"delivery-section\">\n            <h2>Livraison</h2>\n            [text* adresse id:adresse placeholder \"Adresse de livraison\"]\n            [text* code_postal id:code_postal placeholder \"Code postal\"]\n            [text* ville id:ville placeholder \"Ville\"]\n        </div>\n    </div>\n    <div class=\"submit-button\">\n        [submit \"Commander\"]\n    </div>\n</form>');
INSERT INTO `wp_postmeta` VALUES (696,181,'_mail','a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:21:\"Nouvelle Précommande\";s:6:\"sender\";s:12:\"[your-email]\";s:9:\"recipient\";s:23:\"planty.drinks@gmail.com\";s:4:\"body\";s:169:\"Vous avez reçu une nouvelle précommande :\n\nNom : [nom]\nPrénom : [prenom]\nE-mail : [email]\nAdresse de livraison : [adresse]\nCode postal : [code_postal]\nVille : [ville]\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:0;}');
INSERT INTO `wp_postmeta` VALUES (697,181,'_mail_2','a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:23:\"planty.drinks@gmail.com\";s:9:\"recipient\";s:12:\"[your-email]\";s:4:\"body\";s:251:\"Message Body:\n[your-message]\n\n-- L\'Equipe Planty vous remercie\n\n\nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:1;}');
