INSERT INTO `wp_postmeta` VALUES (2223,348,'_form','<!-- Section Fraise -->\n<div style=\"margin-bottom: 40px;\">\n    <h3>Frais</h3>\n    <label>Quantité:</label>\n    [select* fresh-quantity \"1\" \"2\" \"3\" \"4\" \"5\"]\n    <button onclick=\"location.href=\'#precommande\'\" style=\"margin: 5px; background-color: #007BFF; color: #fff; padding: 10px 15px; border: none; border-radius: 5px; cursor: pointer;\">OK</button>\n    [submit \"Ajouter Fraise\"]\n</div>');
