-size: 20px; \\/* Taille du texte *\\/\\n        display: flex; \\/* Aligne le contenu *\\/\\n        justify-content: center; \\/* Centre le contenu *\\/\\n        align-items: center; \\/* Centre verticalement *\\/\\n    }\\n\\n    \\/* Ajout d\'une s\\u00e9paration blanche *\\/\\n    .separator {\\n        height: 4px; \\/* \\u00c9paisseur de la s\\u00e9paration *\\/\\n        background-color: white; \\/* Couleur de la s\\u00e9paration *\\/\\n        width: 100%; \\/* Prend toute la largeur *\\/\\n    }\\n\\n    .spin-buttons button:hover {\\n        background-color: #C02E44; \\/* Change la couleur au survol *\\/\\n    }\\n<\\/style>\",\"_flex_align_self\":\"center\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":false},{\"id\":\"fd56bc8\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"min_height\":{\"unit\":\"px\",\"size\":50,\"sizes\":[]}},\"elements\":[],\"isInner\":false},{\"id\":\"a9ea479\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\"},\"elements\":[{\"id\":\"8d38307\",\"elType\":\"widget\",\"settings\":{\"width\":{\"unit\":\"px\",\"size\":900,\"sizes\":[]},\"width_tablet\":{\"unit\":\"px\",\"size\":\"\",\"sizes\":[]},\"width_mobile\":{\"unit\":\"px\",\"size\":\"\",\"sizes\":[]},\"align\":\"center\",\"text\":\"S\\u00e9parateur\",\"color\":\"#FFFFFF\",\"weight\":{\"unit\":\"px\",\"size\":\"\",\"sizes\":[]}},\"elements\":[],\"widgetType\":\"divider\"}],\"isInner\":false},{\"id\":\"433c73a\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"content_width\":\"full\",\"min_height\":{\"unit\":\"px\",\"size\":50,\"sizes\":[]}},\"elements\":[],\"isInner\":false},{\"id\":\"ffcecab\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":88,\"sizes\":[]},\"flex_align_items\":\"flex-start\"},\"elements\":[{\"id\":\"3565449\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\