de -->\n            <input type=\"submit\" value=\"Commander\">\n    </form>\n</body>\n</html>','page commander ultime planty 1199','','inherit','closed','closed','','1199-revision-v1','','','2024-11-20 19:09:27','2024-11-20 19:09:27','',1199,'http://plantoc.local/?p=1273',0,'revision','',0);
