INSERT INTO `wp_posts` VALUES (1402,1,'2024-12-04 09:13:08','2024-12-04 09:13:08','<h2>COMMANDER</h2>		\n			<h2>Votre commande</h2>		\n			<h6>FRAISE</h6>		\n													<img width=\"393\" height=\"262\" src=\"http://plantoc.local/wp-content/uploads/2024/09/jeremy-bezanger-0QgbyZdhX7k-unsplash-1.png\" alt=\"fraise\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/jeremy-bezanger-0QgbyZdhX7k-unsplash-1.png 393w, http://plantoc.local/wp-content/uploads/2024/09/jeremy-bezanger-0QgbyZdhX7k-unsplash-1-300x200.png 300w, http://plantoc.local/wp-content/uploads/2024/09/elementor/thumbs/jeremy-bezanger-0QgbyZdhX7k-unsplash-1-qukz4zj153l03644p44w1ala850fjwyvbnd42vd8u8.png 192w\" sizes=\"(max-width: 393px) 100vw, 393px\" />													\n    <input type=\"number\" id=\"fraises\" name=\"fraises\" value=\"0\" min=\"0\">\n<style>\n    /* Styles généraux pour l\'input et les boutons */\n    .number-input-container {\n        position: relative;\n        display: inline-block;\n        border-radius: 6px; /* Ajuster l\'arrondi */\n        overflow: hidden; /* Assurer que les boutons suivent l\'arrondi */\n        border: 1px solid #ccc;\n    }\n    input[type=\"number\"] {\n        padding: 5px 2px; /* Réduire le padding */\n        width: 50px; /* Réduire la largeur */\n        font-size: 12px; /* Réduire la taille de la police */\n        text-align: center;\n        box-shadow: none;\n        border: none;\n        outline: none;\n    }\n    .spin-buttons {\n        position: absolute;\n        top: 0;\n        right: 0;\n        width: 20px; /* Réduire la largeur */\n        height: 100%;\n        display: flex;\n        flex-direction: column;\n        background-color: #E0B9B4;\n        border-left: 1px solid #ccc;\n    }\n    .separator {\n        height: 2px; /* Réduire la taille du séparateur */\n        background-color: white;\n        width: 100%;\n    }\n    .spin-buttons button {\n        background-color: transparent;\n        border: none;\n        cursor: pointer;\n        flex: 1;\n        font-size: 12px; /* Réduire la taille de la police */\n        padding: 2px 0; /* Réduire le padding */\n    }\n    /* Effet au survol */\n    .spin-buttons button:hover {\n        background-color: #C02E44;\n    }\n</style>		\n			<h6> PAMPLEMOUSSE</h6>		\n													<img width=\"394\" height=\"263\" src=\"http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-tOitjphtIXU-unsplash-1.png\" alt=\"pamplemousse\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-tOitjphtIXU-unsplash-1.png 394w, http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-tOitjphtIXU-unsplash-1-300x200.png 300w, http://plantoc.local/wp-content/uploads/2024/09/elementor/thumbs/estudio-bloom-tOitjphtIXU-unsplash-1-qukz5qscnambfv0j9xx2jlpngba2r4z33ea6zw8tts.png 192w\" sizes=\"(max-width: 394px) 100vw, 394px\" />													\n    <input type=\"number\" id=\"pamplemousses\" name=\"pamplemousses\" value=\"0\" min=\"0\">\n<style>\n    /* Styles généraux pour l\'input et les boutons */\n    .number-input-container {\n        position: relative;\n        display: inline-block;\n        border-radius: 6px;\n        overflow: hidden;\n        border: 1px solid #ccc;\n    }\n    input[type=\"number\"] {\n        padding: 10px px;\n        width: 60px;\n        font-size: 14px;\n        text-align: center;\n        box-shadow: none;\n        border: none;\n        outline: none;\n    }\n    .spin-buttons {\n        position: absolute;\n        top: 0;\n        right: 0;\n        width: 20px;\n        height: 100%;\n        display: flex;\n        flex-direction: column;\n        background-color: #E0B9B4;\n        border-left: 1px solid #ccc;\n    }\n    .separator {\n        height: 2px;\n        background-color: white;\n        width: 100%;\n    }\n    .spin-buttons button {\n        background-color: transparent;\n        border: none;\n        cursor: pointer;\n        flex: 1;\n        font-size: 14px;\n        padding: 2px 0;\n    }\n    /* Effet au survol */\n    .spin-buttons button:hover {\n        background-color: #C02E44;\n    }\n</style>		\n			<h6>FRAMBOISE </h6>		\n													<img width=\"393\" height=\"262\" src=\"http://plantoc.local/wp-content/uploads/2024/09/rodion-kutsaev-4k8xEFW4_3Q-unsplash-1.png\" alt=\"framboise\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/rodion-kutsaev-4k8xEFW4_3Q-unsplash-1.png 393w, http://plantoc.local/wp-content/uploads/2024/09/rodion-kutsaev-4k8xEFW4_3Q-unsplash-1-300x200.png 300w, http://plantoc.local/wp-content/uploads/2024/09/elementor/thumbs/rodion-kutsaev-4k8xEFW4_3Q-unsplash-1-qukz6mqv3nu2elq43bqdwdnbnewk0uhyjsgpbaxfy8.png 192w\" sizes=\"(max-width: 393px) 100vw, 393px\" />													\n    <input type=\"number\" id=\"framboises\" name=\"framboises\" value=\"0\" min=\"0\">\n<style>\n    body {\n        background-color: white; /* Couleur de fond de la page */\n    }\n    .number-input-container {\n        position: relative;\n        display: inline-block;\n    }\n    input[type=\"number\"] {\n        border-radius: 10px;\n        padding: 31px 4px;\n        border: 1px solid #ccc; /* Épaissir la bordure */\n        width: 100px;\n        font-size: 16px;\n        text-align: center;\n        box-shadow: none; /* Supprimer l\'ombre */\n    }\n    .spin-buttons {\n        position: absolute;\n        top: 0;\n        right: 0;\n        width: 30px; /* Largeur des boutons */\n        height: 100%; /* Hauteur égale à l\'input */\n        background-color: #E0B9B4; /* Couleur de fond des boutons */\n        border-radius: 0 10px 10px 0; /* Arrondi uniquement à droite */\n        display: flex;\n        flex-direction: column;\n        border-left: 2px solid #ccc; /* Ajout d\'une bordure gauche pour démarcation */\n    }\n    .spin-buttons button {\n        background-color: transparent; /* Fond transparent pour les boutons */\n        border: none; /* Supprime le contour */\n        cursor: pointer;\n        flex: 1; /* Remplit l\'espace vertical */\n        padding: 0; /* Pas de padding */\n        font-size: 20px; /* Taille du texte */\n        display: flex; /* Aligne le contenu */\n        justify-content: center; /* Centre le contenu */\n        align-items: center; /* Centre verticalement */\n    }\n    /* Ajout d\'une séparation blanche */\n    .separator {\n        height: 4px; /* Épaisseur de la séparation */\n        background-color: white; /* Couleur de la séparation */\n        width: 100%; /* Prend toute la largeur */\n    }\n    .spin-buttons button:hover {\n        background-color: #C02E44; /* Change la couleur au survol */\n    }\n</style>		\n			<h6>CITRON</h6>		\n													<img width=\"393\" height=\"262\" src=\"http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-ezqnxsqUZ80-unsplash-1.png\" alt=\"citron\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-ezqnxsqUZ80-unsplash-1.png 393w, http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-ezqnxsqUZ80-unsplash-1-300x200.png 300w, http://plantoc.local/wp-content/uploads/2024/09/elementor/thumbs/estudio-bloom-ezqnxsqUZ80-unsplash-1-qukz7d2cf0u3fonvtn3xu708a7au0defzeqar1uf40.png 192w\" sizes=\"(max-width: 393px) 100vw, 393px\" />													\n    <input type=\"number\" id=\"citrons\" name=\"citrons\" value=\"0\" min=\"0\">\n<style>\n    body {\n        background-color: white; /* Couleur de fond de la page */\n    }\n    .number-input-container {\n        position: relative;\n        display: inline-block;\n    }\n    input[type=\"number\"] {\n        border-radius: 10px;\n        padding: 31px 4px;\n        border: 1px solid #ccc; /* Épaissir la bordure */\n        width: 100px;\n        font-size: 16px;\n        text-align: center;\n        box-shadow: none; /* Supprimer l\'ombre */\n    }\n    .spin-buttons {\n        position: absolute;\n        top: 0;\n        right: 0;\n        width: 30px; /* Largeur des boutons */\n        height: 100%; /* Hauteur égale à l\'input */\n        background-color: #E0B9B4; /* Couleur de fond des boutons */\n        border-radius: 0 10px 10px 0; /* Arrondi uniquement à droite */\n        display: flex;\n        flex-direction: column;\n        border-left: 2px solid #ccc; /* Ajout d\'une bordure gauche pour démarcation */\n    }\n    .spin-buttons button {\n        background-color: transparent; /* Fond transparent pour les boutons */\n        border: none; /* Supprime le contour */\n        cursor: pointer;\n        flex: 1; /* Remplit l\'espace vertical */\n        padding: 0; /* Pas de padding */\n        font-size: 20px; /* Taille du texte */\n        display: flex; /* Aligne le contenu */\n        justify-content: center; /* Centre le contenu */\n        align-items: center; /* Centre verticalement */\n    }\n    /* Ajout d\'une séparation blanche */\n    .separator {\n        height: 4px; /* Épaisseur de la séparation */\n        background-color: white; /* Couleur de la séparation */\n        width: 100%; /* Prend toute la largeur */\n    }\n    .spin-buttons button:hover {\n        background-color: #C02E44; /* Change la couleur au survol */\n    }\n</style>		\n			 <!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">  \n    <title>Commander des Fruits</title>\n    <style>\n        body {\n            font-family: Arial, sans-serif;\n            margin: 20px;\n            background-color: #3B8E46; /* Couleur d\'arrière-plan */\n            color: white; /* Couleur du texte en blanc pour contraster */\n        }\n        h1 {\n            text-align: center; /* Centrer le titre principal */\n        }\n        h2 {\n            text-align: left; /* Alignement à gauche pour les sous-titres */\n            margin-bottom: 10px; /* Espacement sous les titres */\n            white-space: nowrap; /* Empêche le texte de se diviser en plusieurs lignes */\n        }\n        .form-container {\n            display: flex; /* Utiliser Flexbox pour l\'alignement horizontal */\n            justify-content: space-between; /* Espacer les sections */\n            gap: 20px; /* Espace entre les sections */\n            margin-bottom: 20px; /* Espace en bas du conteneur */\n        }\n        .info-section, .delivery-section {\n            flex: 1; /* Permet à chaque section de croître également */\n            min-width: 300px; /* Largeur minimum pour les sections */\n            padding: 10px;\n            border: none; /* Aucune bordure */\n            outline: none; /* Pas de contour */\n            background-color: rgba(255, 255, 255, 0.9); /* Fond blanc avec transparence */\n            display: flex; /* Utiliser Flexbox pour la section */\n            flex-direction: column; /* Aligner les éléments en colonne */\n        }\n        .divider {\n            width: 1px; /* Largeur de la ligne */\n            background-color: white; /* Couleur de la ligne */\n            margin: 0 20px; /* Espace autour de la ligne */\n        }\n        label {\n            display: block;\n            margin-bottom: 9px;\n        }\n        input[type=\"text\"], input[type=\"email\"] {\n            width: 400px; /* Largeur augmentée pour rendre les champs plus longs */\n            padding: 8px;\n            margin-bottom: 10px;\n            border: 1px solid #ccc;\n            border-radius: 4px;\n            box-sizing: border-box; /* Inclure le padding dans la largeur */\n            max-width: 100%; /* Empêcher le débordement hors de la page */\n        }\n        .submit-button {\n            text-align: center;\n            margin-top: 20px; /* Espace au-dessus du bouton */\n        }\n        input[type=\"submit\"] {\n            padding: 10px 20px;\n            background-color: #4CAF50;\n            color: white;\n            border: none;\n            border-radius: 4px;\n            cursor: pointer;\n        }\n        input[type=\"submit\"]:hover {\n            background-color: #45a049;\n        }\n    </style>\n</head>\n<body>\n    <h1> </h1>\n    <form action=\"#\" method=\"POST\">\n            <!-- Section d\'informations personnelles -->\n                <h2>Vos informations</h2>\n                <label for=\"nom\">Nom *</label>\n                <input type=\"text\" id=\"nom\" name=\"nom\" required>\n                <label for=\"prenom\">Prénom</label>\n                <input type=\"text\" id=\"prenom\" name=\"prenom\">\n                <label for=\"email\">E-mail *</label>\n                <input type=\"email\" id=\"email\" name=\"email\" required>\n            <!-- Ligne de séparation -->\n            <!-- Section adresse de livraison -->\n                <h2>Livraison</h2>\n                <label for=\"adresse\">Adresse de livraison *</label>\n                <input type=\"text\" id=\"adresse\" name=\"adresse\" required>\n                <label for=\"code_postal\">Code postal *</label>\n                <input type=\"text\" id=\"code_postal\" name=\"code_postal\" required>\n                <label for=\"ville\">Ville *</label>\n                <input type=\"text\" id=\"ville\" name=\"ville\" required>\n        <!-- Bouton de validation de la commande -->\n            <input type=\"submit\" value=\"Commander\">\n    </form>\n</body>\n</html>','page commander ultime planty 1199','','inherit','closed','closed','','1199-revision-v1','','','2024-12-04 09:13:08','2024-12-04 09:13:08','',1199,'http://plantoc.local/?p=1402',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1403,1,'2024-12-04 09:23:25','2024-12-04 09:23:25','<h2>BOISSON ÉNERGISANTE<br> 100% naturelle</h2>		\n													<img width=\"350\" height=\"401\" src=\"http://plantoc.local/wp-content/uploads/2024/09/Group-3.png\" alt=\"fleur droite accueil\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/Group-3.png 350w, http://plantoc.local/wp-content/uploads/2024/09/Group-3-262x300.png 262w\" sizes=\"(max-width: 350px) 100vw, 350px\" />													\n													<img width=\"387\" height=\"618\" src=\"http://plantoc.local/wp-content/uploads/2024/09/Planty6-1.png\" alt=\"canette Planty\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/Planty6-1.png 387w, http://plantoc.local/wp-content/uploads/2024/09/Planty6-1-188x300.png 188w\" sizes=\"(max-width: 387px) 100vw, 387px\" />													\n													<img width=\"350\" height=\"401\" src=\"http://plantoc.local/wp-content/uploads/2024/09/Group-4.png\" alt=\"fleur gauche accueil\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/Group-4.png 350w, http://plantoc.local/wp-content/uploads/2024/09/Group-4-262x300.png 262w\" sizes=\"(max-width: 350px) 100vw, 350px\" />													\n			<h2>L’énergie des plantes</h2>		\n		<p>Planty, c’est la première boisson<br />énergisante composée à 100% de produits naturels.<br />Avec son goût frais et fruité, retrouvez votre<br />énergie grâce aux plantes riches en vitamine B2,<br />à n’importe quel moment de la journée.</p>		\n			<h2>LES GOÛTS</h2>		\n		<p>Nous avons une saveur pour chaque moment de votre journée.</p>		\n										<figure>\n										<img width=\"300\" height=\"200\" src=\"http://plantoc.local/wp-content/uploads/2024/09/jeremy-bezanger-0QgbyZdhX7k-unsplash-1-300x200.png\" alt=\"fraise\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/jeremy-bezanger-0QgbyZdhX7k-unsplash-1-300x200.png 300w, http://plantoc.local/wp-content/uploads/2024/09/elementor/thumbs/jeremy-bezanger-0QgbyZdhX7k-unsplash-1-qukz4zj153l03644p44w1ala850fjwyvbnd42vd8u8.png 192w, http://plantoc.local/wp-content/uploads/2024/09/jeremy-bezanger-0QgbyZdhX7k-unsplash-1.png 393w\" sizes=\"(max-width: 300px) 100vw, 300px\" />											<figcaption>FRAISE</figcaption>\n										</figure>\n										<figure>\n										<img width=\"300\" height=\"200\" src=\"http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-tOitjphtIXU-unsplash-1-300x200.png\" alt=\"pamplemousse\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-tOitjphtIXU-unsplash-1-300x200.png 300w, http://plantoc.local/wp-content/uploads/2024/09/elementor/thumbs/estudio-bloom-tOitjphtIXU-unsplash-1-qukz5qscnambfv0j9xx2jlpngba2r4z33ea6zw8tts.png 192w, http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-tOitjphtIXU-unsplash-1.png 394w\" sizes=\"(max-width: 300px) 100vw, 300px\" />											<figcaption>PAMPLEMOUSSE</figcaption>\n										</figure>\n										<figure>\n										<img width=\"300\" height=\"200\" src=\"http://plantoc.local/wp-content/uploads/2024/09/rodion-kutsaev-4k8xEFW4_3Q-unsplash-1-300x200.png\" alt=\"framboise\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/rodion-kutsaev-4k8xEFW4_3Q-unsplash-1-300x200.png 300w, http://plantoc.local/wp-content/uploads/2024/09/elementor/thumbs/rodion-kutsaev-4k8xEFW4_3Q-unsplash-1-qukz6mqv3nu2elq43bqdwdnbnewk0uhyjsgpbaxfy8.png 192w, http://plantoc.local/wp-content/uploads/2024/09/rodion-kutsaev-4k8xEFW4_3Q-unsplash-1.png 393w\" sizes=\"(max-width: 300px) 100vw, 300px\" />											<figcaption>FRAMBOISE</figcaption>\n										</figure>\n										<figure>\n										<img width=\"300\" height=\"200\" src=\"http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-ezqnxsqUZ80-unsplash-1-300x200.png\" alt=\"citron\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-ezqnxsqUZ80-unsplash-1-300x200.png 300w, http://plantoc.local/wp-content/uploads/2024/09/elementor/thumbs/estudio-bloom-ezqnxsqUZ80-unsplash-1-qukz7d2cf0u3fonvtn3xu708a7au0defzeqar1uf40.png 192w, http://plantoc.local/wp-content/uploads/2024/09/estudio-bloom-ezqnxsqUZ80-unsplash-1.png 393w\" sizes=\"(max-width: 300px) 100vw, 300px\" />											<figcaption>CITRON</figcaption>\n										</figure>\n					<a href=\"http://plantoc.local/page-commander-ultime-planty-1199/\">\n									Commander \n					</a>\n			<h2>CE QU’ILS EN PENSENT </h2>		\n			<h2> Fatiha</h2>		\n		<p>La meilleure boisson énergisante disponible sur le marché !</p>		\n													<img width=\"150\" height=\"150\" src=\"http://plantoc.local/wp-content/uploads/2024/09/Mask-group-4-150x150.png\" alt=\"véro\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/Mask-group-4-150x150.png 150w, http://plantoc.local/wp-content/uploads/2024/09/Mask-group-4-300x300.png 300w, http://plantoc.local/wp-content/uploads/2024/09/Mask-group-4-100x100.png 100w\" sizes=\"(max-width: 150px) 100vw, 150px\" />													\n													<img width=\"150\" height=\"150\" src=\"http://plantoc.local/wp-content/uploads/2024/09/Mask-group-3-150x150.png\" alt=\"fatiha\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/Mask-group-3-150x150.png 150w, http://plantoc.local/wp-content/uploads/2024/09/Mask-group-3-300x300.png 300w, http://plantoc.local/wp-content/uploads/2024/09/Mask-group-3-100x100.png 100w\" sizes=\"(max-width: 150px) 100vw, 150px\" />													\n			<h2> Véro</h2>		\n		<p>Frais &amp; fruité c’est parfait pour accompagner le goûter.</p>		\n													<img width=\"150\" height=\"150\" src=\"http://plantoc.local/wp-content/uploads/2024/09/Mask-group-5-150x150.png\" alt=\"marc\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/Mask-group-5-150x150.png 150w, http://plantoc.local/wp-content/uploads/2024/09/Mask-group-5-300x300.png 300w, http://plantoc.local/wp-content/uploads/2024/09/Mask-group-5-100x100.png 100w\" sizes=\"(max-width: 150px) 100vw, 150px\" />													\n			<h2> Marc</h2>		\n		<p>Un boost d’énergie sans produits chimiques, un vrai plus dans ma journée. </p>		\n														<a href=\"http://plantoc.local/wp-content/uploads/2024/09/Mask-group-1.jpg\" data-elementor-open-lightbox=\"no\">\n							<img width=\"1438\" height=\"162\" src=\"http://plantoc.local/wp-content/uploads/2024/09/Mask-group-1.jpg\" alt=\"cannette groupe\" srcset=\"http://plantoc.local/wp-content/uploads/2024/09/Mask-group-1.jpg 1438w, http://plantoc.local/wp-content/uploads/2024/09/Mask-group-1-300x34.jpg 300w, http://plantoc.local/wp-content/uploads/2024/09/Mask-group-1-1024x115.jpg 1024w, http://plantoc.local/wp-content/uploads/2024/09/Mask-group-1-768x87.jpg 768w, http://plantoc.local/wp-content/uploads/2024/09/Mask-group-1-600x68.jpg 600w\" sizes=\"(max-width: 1438px) 100vw, 1438px\" />								</a>','page accueil ultime planty 1127','','inherit','closed','closed','','1127-revision-v1','','','2024-12-04 09:23:25','2024-12-04 09:23:25','',1127,'http://plantoc.local/?p=1403',0,'revision','',0);
